        self.assertEqual(handler(c), "union")

        Base.register(Concrete)
        self.assertEqual(handler(c), "union")

    def test_pep604_explicit_registration_resolves_ambiguity(self):
        """Explicit registration of the concrete type overrides ambiguous MRO."""
